#define main original_mt_main
#include "original_native/MT.cu"
#undef main
void check(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct Buffer{void*base;void*data;size_t n;Buffer(size_t bytes):n(bytes){check(cudaMalloc(&base,n+512));check(cudaMemset(base,0xa7,n+512));data=(char*)base+256;}~Buffer(){cudaFree(base);}bool guards(std::ofstream&f,int id){std::vector<unsigned char>lo(256),hi(256);check(cudaMemcpy(lo.data(),base,256,cudaMemcpyDeviceToHost));check(cudaMemcpy(hi.data(),(char*)data+n,256,cudaMemcpyDeviceToHost));uint64_t header[]={uint64_t(id),uint64_t(n)};f.write((char*)header,16);f.write((char*)lo.data(),256);f.write((char*)hi.data(),256);return std::all_of(lo.begin(),lo.end(),[](auto x){return x==0xa7;})&&std::all_of(hi.begin(),hi.end(),[](auto x){return x==0xa7;});}};
void append_bytes(std::vector<float>&v,const void*p,size_t n){auto*b=(const unsigned char*)p;for(size_t i=0;i<n;i++)v.push_back(float(b[i]));}
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("data directory, persistent evidence directory, oracle only flag required");std::string data=argv[1],folder=argv[2];std::filesystem::create_directories(folder);initMTRef((data+"/MersenneTwister.raw").c_str());int lengths[]={5860,38,20},repeats[]={3,2,2};unsigned seeds[]={777,0,0xffffffffU};std::vector<mt_struct_stripped>parameters(4096);Buffer dP(4096*sizeof(mt_struct_stripped));Buffer dR(size_t(4096)*5860*4);
 for(int trial=0;trial<=5;trial++){std::vector<float>prefix,output;bool valid=true;double primary=0.;std::ofstream guards,metrics;if(trial){guards.open(folder+"/cuda_trial"+std::to_string(trial)+".guards.bin",std::ios::binary);metrics.open(folder+"/cuda_trial"+std::to_string(trial)+".audit.jsonl");}
  for(int c=0;c<3;c++){int n=lengths[c],rep=repeats[c];unsigned seed=seeds[c];size_t count=size_t(4096)*n;loadMTGPU((data+"/MersenneTwister.dat").c_str(),seed,parameters.data(),4096);check(cudaMemcpy(dP.data,parameters.data(),4096*sizeof(mt_struct_stripped),cudaMemcpyHostToDevice));check(cudaMemset(dR.data,0xa7,dR.n));check(cudaDeviceSynchronize());std::vector<mt_struct_stripped>actualP(4096);if(trial){check(cudaMemcpy(actualP.data(),dP.data,actualP.size()*sizeof(actualP[0]),cudaMemcpyDeviceToHost));valid&=std::memcmp(actualP.data(),parameters.data(),65536)==0;prefix.insert(prefix.end(),{float(c),float(n),float(seed&65535U),float(seed>>16),float(rep),4096.f,128.f});append_bytes(prefix,actualP.data(),65536);}
   auto start=std::chrono::steady_clock::now();for(int r=0;r<rep;r++){mt<<<32,128>>>((const mt_struct_stripped*)dP.data,(float*)dR.data,n);boxmuller<<<32,128>>>((float*)dR.data,n);}check(cudaDeviceSynchronize());double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/rep;if(c==0)primary=seconds;
   if(!trial)continue;std::vector<float>gaussian(count),uniform(count);check(cudaMemcpy(gaussian.data(),dR.data,count*4,cudaMemcpyDeviceToHost));valid&=dP.guards(guards,c*2)&&dR.guards(guards,c*2+1);
   // This is a separately identified deterministic replay, not timed intermediate capture.
   mt<<<32,128>>>((const mt_struct_stripped*)dP.data,(float*)dR.data,n);check(cudaDeviceSynchronize());check(cudaMemcpy(uniform.data(),dR.data,count*4,cudaMemcpyDeviceToHost));auto result=mt_check((const uint32_t*)actualP.data(),uniform.data(),gaussian.data(),n);valid&=!result.uniform_mismatches&&!result.gaussian_failures;
   std::vector<float>gold(count);RandomRef(gold.data(),n,seed);BoxMullerRef(gold.data(),n);double delta=0.,ref=0.;for(int stream=0;stream<4096;stream++)for(int j=0;j<n;j++){double a=gold[size_t(stream)*n+j],b=gaussian[stream+size_t(j)*4096];delta+=std::abs(a-b);ref+=std::abs(a);}double L1=delta/ref;valid&=L1<1e-6;
   metrics<<"{\"case\":"<<c<<",\"nPerRng\":"<<n<<",\"seed\":"<<seed<<",\"checked\":"<<result.checked<<",\"uniform_mismatches\":"<<result.uniform_mismatches<<",\"gaussian_failures\":"<<result.gaussian_failures<<",\"max_abs_error\":"<<result.max_abs_error<<",\"max_bound_fraction\":"<<result.max_bound_fraction<<",\"source_CPU_L1\":"<<L1<<",\"pair_mean_seconds\":"<<seconds<<",\"uniform_capture\":\"untimed_deterministic_MT_replay\"}\n";output.insert(output.end(),gaussian.begin(),gaussian.end());output.insert(output.end(),uniform.begin(),uniform.end());}
 if(!trial)continue;guards.close();metrics.close();size_t inputs=prefix.size();prefix.insert(prefix.end(),output.begin(),output.end());std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"input_prefix_values\":%zu,\"timing_region\":\"source_full4096x5860_MT_BoxMuller_pair_mean3_only\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,primary,valid?"true":"false",prefix.size(),inputs,path.c_str(),prefix.size());fflush(stdout);if(!valid)return 1;}return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
